BEGIN;
CREATE TABLE IF NOT EXISTS customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),code text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS vendors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),code text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS sales_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),customer_id uuid NOT NULL REFERENCES customers(id),invoice_no text NOT NULL,invoice_date date NOT NULL,due_date date NOT NULL,currency_code char(3) NOT NULL DEFAULT 'SAR',total_minor bigint NOT NULL CHECK(total_minor>=0),open_minor bigint NOT NULL CHECK(open_minor>=0 AND open_minor<=total_minor),status text NOT NULL DEFAULT 'open',journal_id uuid REFERENCES journals(id),UNIQUE(organization_id,invoice_no));
CREATE TABLE IF NOT EXISTS customer_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),customer_id uuid NOT NULL REFERENCES customers(id),receipt_date date NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),unapplied_minor bigint NOT NULL CHECK(unapplied_minor>=0),journal_id uuid REFERENCES journals(id));
CREATE TABLE IF NOT EXISTS receipt_allocations(receipt_id uuid NOT NULL REFERENCES customer_receipts(id),invoice_id uuid NOT NULL REFERENCES sales_invoices(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),PRIMARY KEY(receipt_id,invoice_id));
CREATE TABLE IF NOT EXISTS purchase_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),vendor_id uuid NOT NULL REFERENCES vendors(id),invoice_no text NOT NULL,invoice_date date NOT NULL,due_date date NOT NULL,currency_code char(3) NOT NULL DEFAULT 'SAR',total_minor bigint NOT NULL CHECK(total_minor>=0),open_minor bigint NOT NULL CHECK(open_minor>=0 AND open_minor<=total_minor),status text NOT NULL DEFAULT 'open',journal_id uuid REFERENCES journals(id),UNIQUE(organization_id,vendor_id,invoice_no));
CREATE TABLE IF NOT EXISTS vendor_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),vendor_id uuid NOT NULL REFERENCES vendors(id),payment_date date NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),unapplied_minor bigint NOT NULL CHECK(unapplied_minor>=0),journal_id uuid REFERENCES journals(id));
CREATE TABLE IF NOT EXISTS payment_allocations(payment_id uuid NOT NULL REFERENCES vendor_payments(id),invoice_id uuid NOT NULL REFERENCES purchase_invoices(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),PRIMARY KEY(payment_id,invoice_id));
CREATE TABLE IF NOT EXISTS fixed_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),asset_code text NOT NULL,name text NOT NULL,acquisition_date date NOT NULL,cost_minor bigint NOT NULL CHECK(cost_minor>=0),residual_minor bigint NOT NULL DEFAULT 0 CHECK(residual_minor>=0),useful_life_months integer NOT NULL CHECK(useful_life_months>0),status text NOT NULL DEFAULT 'active',UNIQUE(organization_id,asset_code));
CREATE TABLE IF NOT EXISTS asset_depreciation_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),asset_id uuid NOT NULL REFERENCES fixed_assets(id),period_id uuid NOT NULL REFERENCES fiscal_periods(id),amount_minor bigint NOT NULL CHECK(amount_minor>=0),journal_id uuid REFERENCES journals(id),UNIQUE(asset_id,period_id));
COMMIT;
